class Solution {
    public List<List<Integer>> generate(int numRows) {
        List<List<Integer>> res = new ArrayList<>();
        int[][]dp = new int[numRows][numRows];
        dp[0][0] = 1;
        for(int i = 0;i<numRows;i++){
            List<Integer> item = new ArrayList<>();
            for(int j = 0;j<=i;j++){
                if(j==0||j==i){
                    dp[i][j] = 1;
                }else{
                    dp[i][j] = dp[i-1][j]+dp[i-1][j-1];
                }
                item.add(dp[i][j]);
            }
            res.add(item);
        }
        return res;
    }
}
